// Imports the BLUMA stage maps (NES-BLUM-FACTORY-ASSETS/sample-game/levels, BLUM-A3, read-only) as the
// TABLEAU proposals of the sample game BLUM (PLAN §12.3: a FakeProvider replay of hand-authored proposals).
// Output: src/core/sample/blum-levels.ts (propose_level inputs, numeric grid as the grid editor sends it).
// Items (hearts, poutine, syrup) are not entities in the engine yet: they are dropped and listed in the
// generated file. Run: node scripts/import-sample-game.mjs
import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import path from 'node:path';

const root = path.resolve(import.meta.dirname, '..');
const assetsRepo = path.resolve(root, '..', 'NES-BLUM-FACTORY-ASSETS');
const sg = path.join(assetsRepo, 'sample-game');
const commit = execFileSync('git', ['-C', assetsRepo, 'log', '-1', '--format=%h', '--', 'sample-game/levels'], { encoding: 'utf8' }).trim();
const json = (p) => JSON.parse(readFileSync(path.join(sg, p), 'utf8'));
const slug = (s) => s.toLowerCase().replace(/_/g, '-').replace(/[^a-z0-9-]/g, '');

const music = JSON.parse(readFileSync(path.join(assetsRepo, 'music', 'index.json'), 'utf8'));
const WORLDS = ['potager', 'cabane', 'chantier', 'tempete'];
const STAGES = ['w1-s1', 'w1-s2', 'w2-s1', 'w2-s2', 'w3-s1', 'w3-s2', 'w4-s1', 'w4-s2', 'w4-f'];

const levels = [];
const dropped = [];
for (const id of STAGES) {
  const d = json(`levels/${id}.json`);
  if (d.rows !== 13 || d.grid.length !== 13) throw new Error(`${id}: 13 rows expected`);
  const world = WORLDS[d.world - 1];
  const songs = music.worlds[`monde-${d.world}`];
  const entities = [];
  for (const e of d.entities) {
    if (e.type !== 'enemy') {
      dropped.push(`${id} ${e.type} ${e.id} (${e.col},${e.row})`);
      continue;
    }
    entities.push({ actor: slug(e.id), col: e.col, row: e.row, facing: e.col > d.spawn.col ? 'left' : 'right' });
  }
  if (d.bossArena) {
    // the boss box is 32 px wide: its left column, standing on the arena floor row
    entities.push({ actor: slug(d.bossArena.boss), col: Math.floor(d.bossArena.x / 16) - 1, row: d.spawn.row });
  }
  levels.push({
    id,
    name: { fr: d.nameFr, en: d.nameEn },
    world,
    tileset: `tuiles-${world}`,
    width: d.width,
    grid: d.grid,
    spawn: { col: d.spawn.col, row: d.spawn.row },
    entities,
    music: songs.stageSong,
    ...(d.bossArena ? { bossMusic: id === 'w4-f' || d.world === 4 ? 'final' : songs.bossSong } : {}),
    intro: { fr: d.intro_fr, en: d.intro_en },
  });
}

mkdirSync(path.join(root, 'src', 'core', 'sample'), { recursive: true });
const body = levels.map((l) => `  ${JSON.stringify(l)},`).join('\n');
const ts = `// GENERATED by scripts/import-sample-game.mjs from NES-BLUM-FACTORY-ASSETS/sample-game/levels @ ${commit}
// (BLUMA A3, hand-drawn stage maps, original work, see ASSETS.md). Do not edit by hand: re-run the script.
// TABLEAU's propose_level inputs for the sample game BLUM (numeric grid, as the grid editor sends it).
// Not imported (no item entities in the engine yet): ${dropped.length} items, listed in BLUM_DROPPED_ITEMS.

export interface BlumLevelInput {
  id: string;
  name: { fr: string; en: string };
  world: string;
  tileset: string;
  width: number;
  grid: number[][];
  spawn: { col: number; row: number };
  entities: Array<{ actor: string; col: number; row: number; facing?: 'left' | 'right' }>;
  music: string;
  bossMusic?: string;
  /** The map's one-line intro (PLUME folds it into the world intro). */
  intro: { fr: string; en: string };
}

export const BLUM_LEVELS_SOURCE = 'NES-BLUM-FACTORY-ASSETS/sample-game/levels @ ${commit}';

export const BLUM_LEVELS: BlumLevelInput[] = [
${body}
];

export const BLUM_DROPPED_ITEMS: string[] = ${JSON.stringify(dropped, null, 2)};
`;
writeFileSync(path.join(root, 'src', 'core', 'sample', 'blum-levels.ts'), ts);
console.log(`sample game: ${levels.length} stages from ${commit}, ${dropped.length} items dropped`);
